<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\OAuth\UserInvitation\Infrastructure\Driven;

use DateInterval;
use Override;
use Ramsey\Uuid\Uuid;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\AuthenticationResult;
use Civi\Lughauth\Features\OAuth\Authentication\Domain\ChallengesState;
use Civi\Lughauth\Features\OAuth\Client\Domain\Gateway\ClientStoreGateway;
use Civi\Lughauth\Features\OAuth\Session\Domain\Gateway\SessionStoreGateway;
use Civi\Lughauth\Features\OAuth\UserInvitation\Domain\UserInvitationSession;
use Civi\Lughauth\Features\OAuth\UserInvitation\Domain\Gateway\UserInvitationSessionGateway;

class UserInvitationSessionAdapter implements UserInvitationSessionGateway
{
    public function __construct(
        private readonly Context $context,
        private readonly ClientStoreGateway $clients,
        private readonly SessionStoreGateway $sessions,
    ) {
    }

    #[Override]
    public function createSession(
        string $userUid,
        string $email,
        string $tenantUid,
        string $tenantName,
        string $clientId,
    ): ?UserInvitationSession {
        if ($clientId === '') {
            return null;
        }

        $client = $this->clients->findEnabledClient($clientId);
        if ($client === null) {
            return null;
        }

        $issuer = $this->context->getBaseUrl() . '/openid/' . $tenantName;
        $expiration = new DateInterval('P15D');
        $sessionId = Uuid::uuid4()->toString();

        $validation = new AuthenticationResult(
            valid: true,
            id: $userUid,
            tenant: $tenantUid,
            tenantName: $tenantName,
            email: $email,
            name: $email,
        );

        $this->sessions->saveSession(
            $sessionId,
            $client,
            $issuer,
            new ChallengesState(),
            $validation,
            '',
            $expiration,
        );

        return new UserInvitationSession($sessionId, $expiration);
    }
}
